/**
 * Merge platform/AndroidManifest-additions.xml into the generated manifest.
 *
 * `android/` is not committed: lib/ is the app, and the native project is
 * generated by `flutter create`. Generating it produces a manifest with no
 * permissions, so the tracker silently gets no location and no foreground
 * service — it installs, opens, and reports nothing. This puts them back.
 *
 * Idempotent: running it twice changes nothing.
 *
 * `usesCleartextTraffic` is deliberately not applied. The additions file marks
 * it development-only, and a release build talks to https.
 */
import { existsSync, readFileSync, rmSync, writeFileSync } from 'node:fs'

const MANIFEST = 'android/app/src/main/AndroidManifest.xml'
const STOCK_TEST = 'test/widget_test.dart'
const METADATA = '.metadata'
const OPEN = '<manifest xmlns:android="http://schemas.android.com/apk/res/android">'

const PERMISSIONS = [
  'android.permission.INTERNET',
  'android.permission.ACCESS_FINE_LOCATION',
  'android.permission.ACCESS_COARSE_LOCATION',
  /* tracking with the screen locked */
  'android.permission.ACCESS_BACKGROUND_LOCATION',
  'android.permission.FOREGROUND_SERVICE',
  'android.permission.FOREGROUND_SERVICE_LOCATION',
  /* keeps the CPU awake through a shift */
  'android.permission.WAKE_LOCK',
]

const xml = readFileSync(MANIFEST, 'utf8')

if (!xml.includes(OPEN)) {
  console.error(`${MANIFEST}: unexpected shape — the <manifest> tag is not what flutter create used to emit`)
  process.exit(1)
}

const missing = PERMISSIONS.filter((p) => !xml.includes(`"${p}"`))
if (missing.length) {
  const block = missing.map((p) => `    <uses-permission android:name="${p}" />`).join('\n')
writeFileSync(MANIFEST, xml.replace(OPEN, `${OPEN}\n${block}\n`))
console.log(`merged ${missing.length} permission(s):`)
for (const p of missing) console.log(`  ${p.split('.').pop()}`)
} else {
  console.log('permissions already present')
}

/* `flutter create` also writes its counter-app widget test, which asserts on a
   MyApp and an Icons.add that do not exist here — the root widget is
   MirsadDriverApp. It has never compiled, and flutter_test is not a dependency,
   so it fails `flutter analyze` with eighteen errors and takes the build with
   it. Deleting it from the repository was not enough: it comes back every time
   the project is generated, which is once per CI run.

   Only the stock template is removed. The MyApp reference is the tell — a real
   test written later will not mention it, and will survive. */
if (existsSync(STOCK_TEST) && readFileSync(STOCK_TEST, 'utf8').includes('MyApp')) {
  rmSync(STOCK_TEST)
  console.log(`removed ${STOCK_TEST} — the generated counter template, which does not compile here`)
}

/* Generating for android rewrites .metadata's platform list to just what was
   asked for, dropping `web` -- which is still built, and is what /driver/ on
   the site actually serves. Nothing breaks immediately, which is why it kept
   slipping back in: the file only matters to `flutter migrate` later, and by
   then the reason it is wrong is long forgotten. */
const meta = readFileSync(METADATA, 'utf8')

if (!meta.includes('platform: web')) {
  const lines = meta.split('\n')
  const at = lines.findIndex((l) => l.trim() === '- platform: android')

  if (at < 0) {
    console.error(`${METADATA}: no android platform entry to copy the shape from`)
    process.exit(1)
  }

  /* its two revision lines, whatever they happen to be indented by */
  const body = lines.slice(at + 1, at + 3)
  const head = lines[at].replace('android', 'web')
  lines.splice(at + 3, 0, head, ...body)

  writeFileSync(METADATA, lines.join('\n'))
  console.log('restored `platform: web` in .metadata -- generation had dropped it')
}
